do $$ begin if current_database() !~ '^dorm_repair_v2_(dev|test(_[a-z0-9]+)?)$' then raise exception 'Unsafe core target'; end if; end $$;
alter table public.repair_draft drop constraint repair_draft_state_check;
alter table public.repair_draft add constraint repair_draft_state_check check(state in ('EDITABLE','ABANDONED','CONVERTED'));
create table public.v2_order(order_id bigint primary key references public.repair_order(id) on delete restrict,draft_id bigint not null unique references public.repair_draft(id),revision_id bigint not null references public.repair_draft_revision(id),snapshot jsonb not null,version integer not null default 0 check(version>=0),stage varchar(30) not null default 'REVIEW',round_no integer not null default 1 check(round_no>0),process_definition_id varchar(80) not null);
create index ix_v2_order_stage on public.v2_order(stage,order_id);
create table public.v2_worker(user_id bigint primary key references public.sys_user(id),base_building_id bigint references public.building(id),skills jsonb not null default '[]' check(jsonb_typeof(skills)='array'),availability jsonb not null default '[]' check(jsonb_typeof(availability)='array'),capacity integer not null default 3 check(capacity between 1 and 20),version integer not null default 0 check(version>=0));
create table public.v2_appointment(id bigint generated by default as identity primary key,order_id bigint not null references public.repair_order(id),repairer_id bigint not null references public.sys_user(id),start_at timestamptz not null,end_at timestamptz not null,status varchar(20) not null check(status in ('PROPOSED','CONFIRMED','DECLINED','CANCELED')),proposer_id bigint not null references public.sys_user(id),decided_by bigint references public.sys_user(id),reason varchar(500) not null default '',created_at timestamptz not null default current_timestamp,check(start_at<end_at));
create unique index uq_v2_appointment_current on public.v2_appointment(order_id) where status in ('PROPOSED','CONFIRMED');
create index ix_v2_appointment_calendar on public.v2_appointment(repairer_id,status,start_at,end_at);
create table public.v2_order_event(id bigint generated by default as identity primary key,order_id bigint not null references public.repair_order(id),actor_id bigint not null references public.sys_user(id),action varchar(40) not null,note varchar(2000) not null default '',details jsonb not null default '{}',created_at timestamptz not null default current_timestamp);
create index ix_v2_event_order on public.v2_order_event(order_id,id);
create trigger v2_event_immutable before update or delete on public.v2_order_event for each row execute function public.immutable_draft_revision();
create table public.v2_evaluation(order_id bigint primary key references public.repair_order(id),author_id bigint not null references public.sys_user(id),stars integer not null check(stars between 1 and 5),comment varchar(1000) not null default '',created_at timestamptz not null default current_timestamp);
